SELECT login_id AS loginId, agency_employee_num AS employeeNum, agency_id AS agencyId, role, is_locked AS isLocked, is_deleted AS isDeleted, created_at AS createdAt FROM platform_user
agency_id = #{agencyId}
ORDER BY created_at DESC LIMIT #{size} OFFSET #{offset}

SELECT EXISTS (
    SELECT 1 FROM platform_user WHERE login_id = #{loginId}
)

SELECT EXISTS (
    SELECT 1 
    FROM platform_user 
    WHERE agency_id = #{agencyId} 
      AND agency_employee_num = #{employeeNum}
      AND is_deleted = false
)

mapper.update:
UPDATE platform_user
SET is_deleted = true,
    is_locked = true,
    updated_at = #{updatedAt}
WHERE login_id = #{loginId}

UPDATE platform_user
SET password_hash = #{encodedPassword},
    is_locked = false,
    updated_at = #{updatedAt}
WHERE login_id = #{loginId}
